#include <stdio.h>
#include <string.h>

void stuff(const char *in, char *out) {
    int cnt = 0, j = 0;
    for (int i = 0; in[i]; ++i) {
        out[j++] = in[i];
        if (in[i] == '1') {
            cnt++;
            if (cnt == 5) {
                out[j++] = '0';
                cnt = 0;
            }
        } else {
            cnt = 0;
        }
    }
    out[j] = '\0';
}

int main() {
    const char *payload = "1101111110";
    char stuffed[32];
    stuff(payload, stuffed);
    printf("Stuffed: %s\n", stuffed);
    printf("Frame: 01111110%s01111110\n", stuffed);
    return 0;
}
